// handleImagesList processes the image list response
func (m Model) handleImagesList(msg ImagesListMsg) (tea.Model, tea.Cmd) {
	m.loading = false
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] list: %v", msg.Err)
		// Whatever an agent asked for while this was loading is refused with
		// the daemon's reason rather than left waiting (§3.61).
		return m, tea.Batch(
			m.footer.Error("Failed to load images — check logs"),
			m.refusePendingRequests("Cannot list images: "+msg.Err.Error()),
		)
	}
	m.footer.Clear()
	m.images = msg.Images
	m.listed = true
	m.updateImageTable()
	check := checkImageUpdatesCmd(m.updates.Due(pulledImageRefs(m.images), time.Now()))
	if cmd := m.drainPendingRequests(); cmd != nil {
		return m, tea.Batch(cmd, check)
	}
	return m, check
}

// pulledImageRefs are the images worth asking a registry about: tagged, and
// pulled — an image with no registry digest was built or loaded here, and its
// name would send the question to a registry that has never heard of it.
func pulledImageRefs(images []docker.Image) []string {
	var refs []string
	for _, img := range images {
		if img.Tag == "" || img.Tag == "<none>" || len(img.RepoDigests) == 0 {
			continue
		}
		refs = append(refs, img.Name())
	}
	return refs
}

// handleImageUpdatesChecked records the registries' answers.
func (m Model) handleImageUpdatesChecked(msg ImageUpdatesCheckedMsg) (tea.Model, tea.Cmd) {
	m.updates.Store(msg.Facts)
	m.updateImageTable()
	return m, nil
}

// handleScanCacheLoaded updates the scan cache data
func (m Model) handleScanCacheLoaded(msg ScanCacheLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.Entries != nil {
		m.scanCache = msg.Entries
	}
	m.updateImageTable()
	return m, nil
}

// handleImageAction processes action results.
//
// The marker is lifted first, and on every outcome. Clearing it only on success
// would leave the row spinning for the life of the view.
func (m Model) handleImageAction(msg ImageActionMsg) (tea.Model, tea.Cmd) {
	m.imageTable.ClearBusy(msg.ID)
	if msg.Err != nil {
	if m.pullingImage(msg.Image) {
		return m, jobs.Refuse(msg.Invocation, "This image is already being pulled")
	}

	return m, jobs.WithInvocation(msg.Invocation,
		jobs.Start(m.pullRun(msg.Image), pullOneImageCmd(msg.Image)))
}

// deferUntilListed holds a request that arrived before the daemon had answered.
//
// The router builds this view on demand, and building it is not filling it:
// `m.images` is empty until fetchImages returns, so a scan request served
// against it would refuse with "No image ... on this machine" — a statement
// about the daemon that this view is in no position to make yet. See
// workspaces/mcp.go for the same reasoning in full.
func (m *Model) deferUntilListed(msg tea.Msg) (tea.Cmd, bool) {
	if m.listed {
		return nil, false
	}
	m.pendingRequests = append(m.pendingRequests, msg)
	if len(m.pendingRequests) > 1 {
		return nil, true
	}
	return fetchImages(), true
}

// drainPendingRequests re-emits what waited for the listing, as messages, so a
// request that waited takes the same path as one that did not.
func (m *Model) drainPendingRequests() tea.Cmd {
	if len(m.pendingRequests) == 0 {
		return nil
	}
	queued := m.pendingRequests
	m.pendingRequests = nil

	cmds := make([]tea.Cmd, 0, len(queued))
	for _, msg := range queued {
		cmds = append(cmds, func() tea.Msg { return msg })
	}
	return tea.Batch(cmds...)
}

// refusePendingRequests answers everything that waited for a listing that never
// came. An agent would otherwise hang until its own timeout, with the reason in
// a log it cannot see.
func (m *Model) refusePendingRequests(reason string) tea.Cmd {
	if len(m.pendingRequests) == 0 {
		return nil
	}
	queued := m.pendingRequests
	m.pendingRequests = nil

	cmds := make([]tea.Cmd, 0, len(queued))
	for _, msg := range queued {
		if req, ok := msg.(ImageScanRequestedMsg); ok {
			cmds = append(cmds, jobs.Refuse(req.Invocation, reason))
		}
	}
	return tea.Batch(cmds...)
}
