		t.Error("no footer message for an image that is not listed")
	}
}

func TestFocusImageWaitsForTheFirstListing(t *testing.T) {
	m := newTestModel(t)

	m = feed(t, m, FocusImageRequestMsg{Image: "cache:v2"})
	if len(m.pendingRequests) != 1 {
